    """
    Rule: Fill regions bounded by 5s in ANY direction (horizontal or vertical).
    Process iteratively until stable:
      1. Identify all horizontal segments between consecutive 5s on same row -> fill with 3
      2. Identify all vertical segments between consecutive 5s in same column -> fill with 3 IF already has a 3
      3. Repeat steps 1-2 until no changes
    """
    result = grid.copy()
    rows, cols = grid.shape
    changed = True

    while changed:
        changed = False

