            for i in range(len(five_indices) - 1):
                start = five_indices[i] + 1
                end = five_indices[i+1] - 1
                if start > end:
                    continue
                segment_3s = sum(1 for c in range(start, end+1) if result[r,c] == 3)
                if segment_3s > 0:  # Already has some 3s, extend
                    for c in range(start, end+1):
                        if result[r,c] != 3:
                            result[r,c] = 3
                            changed = True
                elif start < end:  # First time encountering this segment
                    for c in range(start, end+1):
                        if result[r,c] != 3:  # Fill if not 5
                            result[r,c] = 3
                            changed = True

        # Step 2: Vertical fills (bounded by 5s, extend from existing 3s)
        for c in range(cols):
            five_rows = sorted([r for r in range(rows) if result[r,c] == 5])
            for i in range(len(five_rows) - 1):
